// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

export interface ParameterGroupResult {
  readonly mappedParameters: Record<string, string>;
  readonly findings: TranslationFinding[];
}

/**
 * Resolves AWS RDS parameter group parameters to their target-provider
 * equivalents, emitting findings for unmapped or unsupported parameters.
 *
 * @param resourceId     - Source resource ID for findings attribution
 * @param engine         - RDS engine type (postgres, mysql, sqlserver, etc.)
 * @param targetProvider - Target cloud provider ('azure' | 'gcp')
 * @param parameters     - Map of AWS parameter name to value
 */
export function resolveParameterGroup(
  resourceId: string,
  engine: string,
  targetProvider: 'azure' | 'gcp',
  parameters: Readonly<Record<string, string>>,
): ParameterGroupResult {
  const findings: TranslationFinding[] = [];

  // Normalise engine to base key (sqlserver-ee -> sqlserver)
  const engineBase = engine.startsWith('sqlserver') ? 'sqlserver' : engine;
  const paramTable = ENGINE_PARAM_TABLES.get(engineBase);

  if (!paramTable) {
    findings.push(
      createFinding(
        resourceId,
        'warning',
        'RDS_PARAMETER_GROUP_UNKNOWN_ENGINE',
        `Parameter group references unknown engine '${engine}'; parameters cannot be mapped`,
      ),
    );
    return { mappedParameters: {}, findings };
  }

  const mappedParameters: Record<string, string> = {};

  for (const [paramName, paramValue] of Object.entries(parameters)) {
    const mapping = paramTable.get(paramName);
    if (!mapping) {
      findings.push(
        createFinding(
          resourceId,
          'info',
          'RDS_PARAMETER_UNMAPPED',
          `Parameter '${paramName}' has no known ${targetProvider} equivalent; skipped`,
        ),
      );
      continue;
    }

    const targetName = targetProvider === 'azure' ? mapping.azure : mapping.gcp;
    mappedParameters[targetName] = paramValue;
  }

  return { mappedParameters, findings };
}
